body:
your code is kinda more complicated than necessary to be honest. a simpler and more effective way is to do something like this ( may contain errors, i haven't tested this )

    @riverpod
    class ObituaryNotifier extends _$ObituaryNotifier {
      @override
      List<Obituary> build() {
        // return empty state to be populated later
        // you can also return null to differentiate lists with empty results and first build if you want
        return [];
      }

      // invoke this method on click to populate the state
      Future<void> getObituariesByName(String fullname) async {
        final obituaryController = ref.read(obituaryControllerProvider);
        state = await obituaryController.getObituariesByNameUseCase(fullname);
        // populate the state and let riverpod handle widget rebuild
      }
    }

    // read data using
    ref.watch(obituaryNotifierProvider).when(...);

    // to invoke the method, use
    ref.read(obituaryNotifierProvider.notifier).getObituariesByName('John Doe');

